    for label, expectation in setup_completion_expectations.items():
        setup_completion_payload = setup_completion_payloads[label]
        (
            expected_state,
            expected_blocker,
            expected_reason,
            expected_profile,
            expected_config,
            expected_no_secrets,
            expected_validation,
            expected_persistence,
            expected_reset,
            expected_setup_gate,
            expected_sdk_handoff,
            expected_setup_consent,
        ) = expectation
        _require(
            setup_completion_payload["stateId"]
            == ai_provider_state.FAM007_PROVIDER_SETUP_COMPLETION_FOUNDATION_STATE_ID
            and setup_completion_payload["mode"]
            == ai_provider_state.FAM007_PROVIDER_SETUP_COMPLETION_FOUNDATION_MODE,
            f"{label} setup-completion fixture must use setup completion identity",
            failures,
        )
        _require(
            setup_completion_payload["providerSetupCompletionStateSchemaVersion"]
            == ai_provider_state.SETUP_COMPLETION_STATE_SCHEMA_VERSION
            and setup_completion_payload[
                "providerSetupCompletionConfigSchemaVersion"
            ]
            == ai_provider_state.SETUP_COMPLETION_CONFIG_SCHEMA_VERSION,
            f"{label} setup-completion fixture must publish setup completion schemas",
            failures,
        )
        _require(
            setup_completion_payload["providerSetupCompletionState"]
            == expected_state
            and setup_completion_payload["providerSetupCompletionBlockerState"]
            == expected_blocker
            and setup_completion_payload["providerSetupCompletionReasonCode"]
            == expected_reason
            and setup_completion_payload["providerSetupCompletionProfileStatus"]
            == expected_profile
            and setup_completion_payload["providerSetupCompletionConfigStatus"]
            == expected_config
            and setup_completion_payload["providerSetupCompletionNoSecretsStatus"]
            == expected_no_secrets
            and setup_completion_payload[
                "providerSetupCompletionValidationStatus"
            ]
            == expected_validation
            and setup_completion_payload[
                "providerSetupCompletionPersistenceStatus"
            ]
            == expected_persistence
            and setup_completion_payload["providerSetupCompletionResetState"]
            == expected_reset
            and setup_completion_payload[
                "providerSetupCompletionProviderSetupGateState"
            ]
            == expected_setup_gate
            and setup_completion_payload[
                "providerSetupCompletionProviderExecutionGateState"
            ]
            == ai_provider_state.SETUP_COMPLETION_PROVIDER_EXECUTION_GATE_DISABLED
            and setup_completion_payload[
                "providerSetupCompletionSdkHandoffState"
            ]
            == expected_sdk_handoff
            and setup_completion_payload[
                "providerSetupCompletionSetupConsentState"
            ]
            == expected_setup_consent,
            f"{label} setup-completion fixture must derive local completion, reset, and handoff posture",
            failures,
        )
        _require(
            setup_completion_payload["providerSetupCompletionStatusProofState"]
            == ai_provider_state.SETUP_COMPLETION_STATUS_PROOF_PUBLIC_LOCAL_ASSIST
            and setup_completion_payload[
                "providerSetupCompletionDesktopDisplayState"
            ]
            == ai_provider_state.SETUP_COMPLETION_DESKTOP_DISPLAY_VISIBLE
            and setup_completion_payload["desktopAiOwnedReadinessDisplayState"]
            == AI_PROVIDER_STATUS_DISPLAY_VISIBLE
            and setup_completion_payload["interactionAffordance"]
            == ai_provider_state.LOCAL_ASSISTED_INTERACTION_AFFORDANCE
            and setup_completion_payload["interactionLabel"]
            == "Run no-provider check",
            f"{label} setup-completion fixture must publish visible no-provider status",
            failures,
        )
        _require(
            setup_completion_payload["localActionResultSchemaVersion"]
            == LOCAL_ACTION_RESULT_SCHEMA_VERSION
            and setup_completion_payload["localActionResultState"]
            == LOCAL_ACTION_RESULT_DETERMINISTIC_NO_PROVIDER
            and setup_completion_payload["localActionResultLabel"]
            == "No-provider check: no provider configured"
            and "provider-visible data remains none"
            in setup_completion_payload["localActionResultDetail"]
            and setup_completion_payload["localActionResultProviderVisibleData"]
            == "none"
            and setup_completion_payload["localActionResultSentToProvider"]
            is False
            and setup_completion_payload["localActionResultCanAcceptPrompts"]
            is False
            and setup_completion_payload["localActionResultPromptSendPosture"]
            == PROMPT_SEND_POSTURE_DISABLED
            and setup_completion_payload["localActionResultNetworkEgressState"]
            == NETWORK_EGRESS_BLOCKED
            and setup_completion_payload["localActionResultMemoryIndexingState"]
            == MEMORY_INDEXING_DISABLED,
            f"{label} setup-completion fixture must expose deterministic no-provider result proof",
            failures,
        )
        _require(
            setup_completion_payload["aiControlCenterDiagnosticsSchemaVersion"]
            == ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTICS_SCHEMA_VERSION
            and setup_completion_payload["aiControlCenterDiagnosticState"]
            == ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_NO_PROVIDER_FAIL_CLOSED
            and setup_completion_payload["aiControlCenterDiagnosticLabel"]
            == "No provider configured; fail-closed"
            and setup_completion_payload["aiControlCenterProviderBoundaryLabel"]
            == "Provider boundary: blocked"
            and setup_completion_payload["aiControlCenterBlockedActionLabel"]
            == "Prompt/provider/model action blocked"
            and setup_completion_payload["aiControlCenterUnavailableCapabilityLabel"]
            == "Capability packs unavailable"
            and setup_completion_payload["aiControlCenterRecoveryLabel"]
            == "Retry local check only"
            and setup_completion_payload["aiControlCenterDegradedPathLabel"]
            == "Local guidance only",
            f"{label} setup-completion fixture must expose AI Control Center diagnostic copy",
            failures,
        )
        diagnostic_states = {
            item.get("state")
            for item in setup_completion_payload["aiControlCenterStateTaxonomy"]
        }
        _require(
            diagnostic_states
            == {
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_NO_PROVIDER_FAIL_CLOSED,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_PROVIDER_UNAVAILABLE,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_STALE_STATE,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_FAILED_CHECK,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_RETRY_LOCAL_ONLY,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_RECOVERY_LOCAL_ONLY,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_BLOCKED_ACTION,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_UNAVAILABLE_CAPABILITY,
                ai_provider_state.AI_CONTROL_CENTER_DIAGNOSTIC_DEGRADED_NO_PROVIDER,
            },
            f"{label} setup-completion fixture must publish the complete AI Control Center diagnostic taxonomy",
            failures,
        )
        _require(
            setup_completion_payload["capabilityPackEligibilityLabel"]
            == "Capability-pack eligibility: blocked until local capability proof",
            f"{label} setup-completion fixture must visibly disclose blocked capability-pack eligibility",
            failures,
        )
        _require(
            setup_completion_payload["installIntentLabel"]
            == "Install intent: blocked; downloads and install execution remain disabled",
            f"{label} setup-completion fixture must visibly disclose blocked install intent",
            failures,
        )
        _require(
            setup_completion_payload["laneBoundarySchemaVersion"] == LANE_BOUNDARY_SCHEMA_VERSION
            and setup_completion_payload["publicLaneBoundaryState"]
            == PUBLIC_LANE_BOUNDARY_LOCAL_ASSIST_ONLY
            and setup_completion_payload["developerLaneBoundaryState"]
            == DEVELOPER_LANE_BOUNDARY_PRIVATE_SETUP_BLOCKED
            and setup_completion_payload["ownerLaneBoundaryState"]
            == OWNER_LANE_BOUNDARY_PRIVATE_SETUP_BLOCKED
            and setup_completion_payload["privateSetupBoundaryState"]
            == PRIVATE_SETUP_BOUNDARY_BLOCKED
            and setup_completion_payload["privateSetupAuthorized"] is False
            and setup_completion_payload["privateMaterialVisible"] is False
            and setup_completion_payload["ownerMemoryEnabled"] is False
            and setup_completion_payload["ownerAgentsEnabled"] is False,
            f"{label} setup-completion fixture must expose public-safe lane boundaries with private setup blocked",
            failures,
        )
        for key, expected in {
            "publicLaneBoundaryLabel": "Public Edition: deterministic no-provider assist; provider-visible data none",
            "developerLaneBoundaryLabel": "Developer lane: gated; private setup not configured",
            "ownerLaneBoundaryLabel": "Owner lane: gated; private setup not configured",
        }.items():
            _require(
                setup_completion_payload[key] == expected,
                f"{label} setup-completion fixture lane boundary label {key} mismatch",
                failures,
            )
        _require(
            setup_completion_payload["providerSetupCompletionProviderVisibleData"]
            == "none"
            and setup_completion_payload["providerSetupCompletionSentToProvider"]
            is False
            and setup_completion_payload[
                "providerSetupCompletionCanAcceptPrompts"
            ]
            is False
            and setup_completion_payload["providerVisibleData"] == "none"
            and setup_completion_payload["sentToProvider"] is False
            and setup_completion_payload["canAcceptPrompts"] is False,
            f"{label} setup-completion fixture must keep provider-visible data and prompts closed",
            failures,
        )
        _require(
            setup_completion_payload["promptSendPosture"]
            == PROMPT_SEND_POSTURE_DISABLED
            and setup_completion_payload["modelExecutionStatus"]
            == MODEL_EXECUTION_STATUS_DISABLED
            and setup_completion_payload["providerExecutionGateState"]
            == PROVIDER_EXECUTION_GATE_DISABLED
            and setup_completion_payload["providerSetupCompletionNetworkEgressState"]
            == NETWORK_EGRESS_BLOCKED
            and setup_completion_payload["networkEgressState"]
            == NETWORK_EGRESS_BLOCKED
            and setup_completion_payload["providerSetupCompletionMemoryState"]
            == MEMORY_INDEXING_DISABLED
            and setup_completion_payload["memoryIndexingState"]
            == MEMORY_INDEXING_DISABLED
            and setup_completion_payload["providerSetupCompletionVoiceState"]
            == "voice-runtime-disabled"
            and setup_completion_payload["voiceRuntimeState"]
            == "voice-runtime-disabled",
            f"{label} setup-completion fixture must not enable model, network, memory, or voice paths",
            failures,
        )
        _require(
            setup_completion_payload[
                "providerSetupCompletionFunctionalAiCriteriaState"
            ]
            == ai_provider_state.SETUP_COMPLETION_FUNCTIONAL_AI_CRITERIA_PENDING
            and setup_completion_payload[
                "providerSetupCompletionV18ContinuationState"
            ]
            == ai_provider_state.SETUP_COMPLETION_V18_CONTINUATION_PENDING,
            f"{label} setup-completion fixture must keep functional AI and v1.8.0 future-gated",
            failures,
        )

    original_durable_loader = ai_provider_state.load_provider_durable_consent_record
    durable_loader_calls: list[object] = []
    first_loaded_record = normalize_provider_durable_consent_record(
        _durable_consent_record(
            setup_consent_granted=True,
            execution_consent_granted=False,
        ),
        now_utc=fixed_now,
    )
    second_loaded_record = normalize_provider_durable_consent_record(
        _durable_consent_record(revoked=True),
        now_utc=fixed_now,
    )

    def _changing_durable_loader(
        store_dir: str | Path | None,
        *,
        now_utc: datetime | None = None,
    ):
        durable_loader_calls.append((store_dir, now_utc))
        if len(durable_loader_calls) == 1:
            return first_loaded_record
        return second_loaded_record

    ai_provider_state.load_provider_durable_consent_record = _changing_durable_loader
    try:
        single_snapshot_consent_ux = (
            ai_provider_state.build_provider_user_operated_consent_ux_foundation_state(
                execution_ready_readiness_config,
                activation_config=execution_ready_activation_config,
                path_consent_config=setup_foundation_future_branch_path_config,
                setup_foundation_config=consent_collection_ready_setup_config,
                consent_collection_config=consent_capture_ready_collection_config,
                consent_capture_record=_consent_capture_record(
                    setup_consent_granted=True
                ),
                durable_consent_store_dir=Path("validator-single-durable-snapshot"),
                now_utc=fixed_now,
                surface_role="core",
            )
        )
    finally:
        ai_provider_state.load_provider_durable_consent_record = original_durable_loader

    single_snapshot_payload = single_snapshot_consent_ux.as_renderer_payload()
    _require(
        len(durable_loader_calls) == 1,
        "consent UX derivation must reuse the already-built durable snapshot instead of reloading durable consent",
        failures,
    )
    _require(
        single_snapshot_payload["durableConsentRecordState"]
        == CONSENT_DURABLE_RECORD_STATE_READY
        and single_snapshot_payload["consentUxState"]
        == CONSENT_UX_STATE_READY_LOCAL_ONLY
        and single_snapshot_payload["consentUxSetupDisplayState"]
        == CONSENT_DURABLE_CONSENT_STATE_GRANTED
        and single_snapshot_payload["consentUxRevocationResetState"]
        == CONSENT_UX_STATE_READY_LOCAL_ONLY,
        "consent UX state must derive from the single durable snapshot already present in provider state",
        failures,
    )

    previous_durable_store_override = os.environ.get(
        ai_provider_state.CONSENT_DURABLE_STORE_DIR_ENV
    )
    durable_store_override = Path("validator-durable-consent-store-override")
    os.environ[ai_provider_state.CONSENT_DURABLE_STORE_DIR_ENV] = str(
        durable_store_override
    )
    try:
        resolved_durable_store_override = (
            ai_provider_state.resolve_default_provider_durable_consent_store_dir()
        )
    finally:
        if previous_durable_store_override is None:
            os.environ.pop(ai_provider_state.CONSENT_DURABLE_STORE_DIR_ENV, None)
        else:
            os.environ[
                ai_provider_state.CONSENT_DURABLE_STORE_DIR_ENV
            ] = previous_durable_store_override

    _require(
        resolved_durable_store_override == durable_store_override,
        "durable consent store resolver must honor the explicit local store override",
        failures,
    )
